<?php
require dirname(__DIR__).'/bootstrap.php';
use App\Support\Database;
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function sv(mixed $v,string $s=''):string{return $v===null?'—':e($v).$s;}function initials(string $v):string{$p=preg_split('/\s+/',trim($v));return strtoupper(substr($p[0]??'',0,1).substr($p[1]??'',0,1));}
$id=trim((string)($_GET['id']??''));$fixture=null;$stats=[];$competitions=[];
try{$pdo=Database::connection();$competitions=$pdo->query("SELECT name,country_name,logo FROM competitions WHERE prediction_enabled=1 ORDER BY country_name,name LIMIT 8")->fetchAll(PDO::FETCH_ASSOC);if($id!==''){$q=$pdo->prepare("SELECT f.*,c.name competition_name,c.country_name,c.logo competition_logo,h.name home_name,h.logo home_logo,a.name away_name,a.logo away_logo FROM fixtures f JOIN competitions c ON c.id=f.competition_id JOIN teams h ON h.id=f.home_team_id JOIN teams a ON a.id=f.away_team_id WHERE f.provider_id=? LIMIT 1");$q->execute([$id]);$fixture=$q->fetch(PDO::FETCH_ASSOC)?:null;if($fixture){$s=$pdo->prepare("SELECT * FROM team_match_stats WHERE fixture_id=? AND period='MATCH'");$s->execute([$fixture['id']]);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r)$stats[(int)$r['team_id']]=$r;}}}catch(Throwable){}
if(!$fixture)http_response_code(404);$hs=$fixture?($stats[(int)$fixture['home_team_id']]??[]):[];$as=$fixture?($stats[(int)$fixture['away_team_id']]??[]):[];$activePage='matches';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$fixture?e($fixture['home_name'].' vs '.$fixture['away_name']):'Match not found'?> — Puntly</title><link rel="stylesheet" href="assets/app.css"></head><body><?php require __DIR__.'/partials/header.php';?><div class="shell"><div class="layout"><aside class="leftbar"><div class="sidebar-title">COMPETITIONS WE COVER</div><div class="card league-list"><div class="league-head">⚽ &nbsp; Football</div><?php foreach($competitions as $c):?><a class="league-link" href="/"><span class="league-logo"><?php if($c['logo']):?><img src="<?=e($c['logo'])?>"><?php else:?>⚽<?php endif;?></span><span style="min-width:0"><div class="league-name"><?=e($c['name'])?></div><div class="league-country"><?=e($c['country_name']?:'International')?></div></span></a><?php endforeach;?></div></aside><main><?php if(!$fixture):?><div class="card empty"><strong style="display:block;color:#17191c;font-size:18px;margin-bottom:8px">Match not found</strong>The requested fixture is not available in the local dataset.</div><?php else:?><div class="crumb"><a href="/" style="color:inherit;text-decoration:none">Matches</a> &nbsp;/&nbsp; <?=e($fixture['competition_name'])?><?php if($fixture['round_name']):?> &nbsp;/&nbsp; <?=e($fixture['round_name'])?><?php endif;?></div><section class="card match-hero"><div class="scoreboard"><div class="club"><span class="team-logo"><?php if($fixture['home_logo']):?><img src="<?=e($fixture['home_logo'])?>"><?php else:?><?=e(initials($fixture['home_name']))?><?php endif;?></span><h1><?=e($fixture['home_name'])?></h1></div><div class="score-center"><span class="status"><?=e($fixture['status'])?></span><div class="big-score"><?=$fixture['home_score']!==null?e($fixture['home_score'].' : '.$fixture['away_score']):'VS'?></div><div class="kickoff"><?=e($fixture['kickoff'])?> UTC</div></div><div class="club"><span class="team-logo"><?php if($fixture['away_logo']):?><img src="<?=e($fixture['away_logo'])?>"><?php else:?><?=e(initials($fixture['away_name']))?><?php endif;?></span><h1><?=e($fixture['away_name'])?></h1></div></div><?php if($fixture['venue']||$fixture['referee_name']):?><div class="meta-row"><?php if($fixture['venue']):?><span>Venue · <?=e($fixture['venue'])?></span><?php endif;?><?php if($fixture['referee_name']):?><span>Referee · <?=e($fixture['referee_name'])?></span><?php endif;?></div><?php endif;?></section><div class="content-grid" style="margin-top:15px"><section class="card"><div class="panel-head"><div><div class="section-label">Match data</div><h2 style="margin-top:4px">Team statistics</h2></div><span class="subtext">Full match</span></div><?php if(!$hs&&!$as):?><div class="empty">Statistics have not been imported for this match yet.</div><?php else:?><div class="stat-table"><?php foreach([['xg','Expected goals'],['possession','Possession','%'],['shots','Shots'],['shots_on_target','Shots on target'],['big_chances','Big chances'],['corners','Corners'],['fouls','Fouls'],['yellow_cards','Yellow cards'],['red_cards','Red cards']] as $m):?><div class="stat-row"><b><?=sv($hs[$m[0]]??null,$m[2]??'')?></b><span><?=e($m[1])?></span><b><?=sv($as[$m[0]]??null,$m[2]??'')?></b></div><?php endforeach;?></div><?php endif;?></section><aside><section class="card forecast"><div class="section-label" style="color:var(--brand-dark)">Puntly forecast</div><h3>Model preparing</h3><p>Probabilities will be published after the historical dataset and feature pipeline pass validation.</p><div class="prob-grid"><?php foreach(['Home','Draw','Away'] as $l):?><div class="prob"><small><?=$l?></small><strong>—</strong></div><?php endforeach;?></div></section><section class="card forecast" style="margin-top:12px"><div class="section-label">Confidence index</div><h3 style="font-size:25px">— <small style="font-size:10px;color:#9ba1aa">/ 100</small></h3><p>Based on data completeness, model agreement, calibration, sample size and freshness.</p></section></aside></div><?php endif;?></main><aside class="rightbar"><div class="card side-info"><h3>Puntly Intelligence</h3><div class="status-box"><div class="status-title">● DATA ENGINE ACTIVE</div><div class="status-copy">Match data is being collected and validated before forecasts are made public.</div></div><?php foreach([['Result model','Preparing'],['Goals model','Preparing'],['Shots model','Queued'],['Corners model','Queued']] as $m):?><div class="model-line"><span><?=$m[0]?></span><span><?=$m[1]?></span></div><?php endforeach;?><a class="button-dark" href="/performance.php">Model performance</a></div></aside></div><footer class="footer"><span>© <?=date('Y')?> Puntly</span><span>Probabilities are estimates, not guarantees.</span></footer></div></body></html>